CREATE OR REPLACE FUNCTION app.m07_sealed_inspection() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='completed' OR TG_OP='DELETE' THEN RAISE EXCEPTION 'COMPLETED_INSPECTION_IMMUTABLE' USING ERRCODE='55000'; END IF; RETURN NEW; END;$$;
CREATE OR REPLACE FUNCTION app.m07_sealed_item() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'COMPLETED_INSPECTION_IMMUTABLE' USING ERRCODE='55000'; END IF; RETURN NEW; END;$$;
